  <script>
    // 全局变量
    const fullInput = `
$1
`;

    // 生成下划线
    function generateUnderlines() {
      const contentEl = document.querySelector('.letter-content');
      const textSizer = document.querySelector('.letter-text-sizer');

      // 移除现有的下划线容器
      const existingUnderlines = document.querySelector('.text-underline');
      if (existingUnderlines) {
        existingUnderlines.remove();
      }

      // 创建新的下划线容器
      const underlineContainer = document.createElement('div');
      underlineContainer.className = 'text-underline';
      contentEl.parentNode.insertBefore(underlineContainer, contentEl);

      // 获取所有文本节点和<br>标签
      const textNodes = [];
      const walker = document.createTreeWalker(
        contentEl,
        NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT,
        {
          acceptNode: function(node) {
            if (node.nodeType === Node.TEXT_NODE && node.textContent.trim()) {
              return NodeFilter.FILTER_ACCEPT;
            }
            if (node.nodeType === Node.ELEMENT_NODE && node.tagName === 'BR') {
              return NodeFilter.FILTER_ACCEPT;
            }
            if (node.nodeType === Node.ELEMENT_NODE && node.classList.contains('dialog-box')) {
              return NodeFilter.FILTER_SKIP;
            }
            return NodeFilter.FILTER_SKIP;
          }
        }
      );

      let currentNode;
      while (currentNode = walker.nextNode()) {
        if (currentNode.nodeType === Node.TEXT_NODE || currentNode.tagName === 'BR') {
          textNodes.push(currentNode);
        }
      }

      // 为每个文本段落添加下划线
      let currentY = 0;
      let lastWasBR = false;

      textNodes.forEach((node, index) => {
        if (node.tagName === 'BR') {
          currentY += 40; // 行高
          lastWasBR = true;
          return;
        }

        const range = document.createRange();
        range.selectNode(node);
        const rect = range.getBoundingClientRect();
        const containerRect = contentEl.getBoundingClientRect();
        const relativeY = rect.top - containerRect.top;

        // 只在非对话框区域添加下划线
        if (!node.parentElement.closest('.dialog-box')) {
          const underline = document.createElement('div');
          underline.className = 'underline-line';
          underline.style.top = `${relativeY + 35}px`; // 35px是行高的一半多一点
          underlineContainer.appendChild(underline);
        }

        lastWasBR = false;
      });
    }

    // 解析评测数据
    function parseExaminationData() {

      // 查找<examination>标签的位置
      const examStart = fullInput.indexOf('<examination>');
      const examEnd = fullInput.indexOf('</examination>');

      // 当未检测到<examination>时隐藏试卷
      const paperEl = document.querySelector('.white-rectangle');
      if (examStart === -1 || examEnd === -1) {
        if (paperEl) {
          paperEl.style.display = 'none';
        }
        return;
      } else if (paperEl) {
        paperEl.style.display = '';
      }

      // 提取<examination>标签内的内容
      const examinationData = fullInput.substring(examStart + '<examination>'.length, examEnd).trim();
      const parts = examinationData.split('|');

      // 填充标题
      if (parts.length > 0) {
        document.querySelector('.test-title .blank:nth-child(1)').textContent = parts[0];
      }
      if (parts.length > 1) {
        document.querySelector('.test-title .blank:nth-child(2)').textContent = parts[1];
      }

      // 填充评测内容
      const evalTexts = document.querySelectorAll('.eval-text');
      const evalScores = document.querySelectorAll('.eval-score');

      for (let i = 0; i < 6 && i * 2 + 2 < parts.length; i++) {
        evalTexts[i].textContent = parts[i * 2 + 2] || '';
        evalScores[i].textContent = parts[i * 2 + 3] || '';
      }

      // 填充总评
      if (parts.length > 14) {
        evalTexts[6].textContent = parts[parts.length - 1];
      }

      // 根据评分更新图片
      updateImageByScore();
    }

    // 解析对话格式
    function parseDialogFormat(text) {
      // 匹配格式：<心奈|表情|对话内容>
      const dialogRegex = /<([^|]+)\|([^|]+)\|([^>]+)>/g;

      return text.replace(dialogRegex, function(match, character, expression, dialogue) {
        // 获取表情对应的图片URL
        let avatarUrl = '';
        if (character === '心奈' && kokonaExpressions[expression]) {
          avatarUrl = kokonaExpressions[expression];
        } else {
          // 如果找不到对应表情，使用默认表情
          avatarUrl = kokonaExpressions.normal || 'https://files.catbox.moe/2wxy0m.jpg';
        }

        // 生成对话框HTML
        return `<div class="dialog-box">
          <img src="${avatarUrl}" alt="${character}" class="dialog-avatar">
          <div class="dialog-content">
            <div class="dialog-name">${character}</div>
            <div>${dialogue}</div>
          </div>
        </div>`;
      });
    }

    // 将当前正文的HTML转换为纯文本（对话框替换为“名字：内容”）并同步到测量容器
    function syncTextSizerFromContent() {
      const contentEl = document.querySelector('.letter-content');
      const textSizer = document.querySelector('.letter-text-sizer');
      const temp = document.createElement('div');
      temp.innerHTML = contentEl.innerHTML;
      const boxes = temp.querySelectorAll('.dialog-box');
      boxes.forEach((box) => {
        const name = box.querySelector('.dialog-name')?.textContent || '';
        const text = box.querySelector('.dialog-content div:last-child')?.textContent || '';
        const replacement = document.createElement('div');
        replacement.textContent = name ? `${name}：${text}` : text;
        box.replaceWith(replacement);
      });
      textSizer.textContent = temp.innerText || temp.textContent || '';
    }

    // 设置正文内容
    function setLetterContent() {

      // 查找<examination>标签的位置
      const examStart = fullInput.indexOf('<examination>');

      // 提取<examination>前面的内容作为正文
      let content = '';
      if (examStart !== -1) {
        content = fullInput.substring(0, examStart).trim();
      } else {
        content = fullInput;
      }

      // 先处理对话格式
      content = parseDialogFormat(content);

      // 将换行符转换为HTML换行标签
      content = content.replace(/\n/g, '<br>');

      const contentEl = document.querySelector('.letter-content');
      contentEl.innerHTML = content;
      // 生成下划线（只在非对话区域）
      setTimeout(generateUnderlines, 10);
    }

    // 随机旋转图片
