      if (image) {
        // 生成-30到+30度之间的随机角度
        const randomAngle = (Math.random() - 0.5) * 60; // -30 到 +30 度
        image.style.transform = `rotate(${randomAngle}deg)`;
      }
    }

    // 心奈表情映射
    const kokonaExpressions = {
      正常: 'https://files.catbox.moe/2wxy0m.jpg',          // 正常
      抿嘴笑: 'https://files.catbox.moe/ql0f90.jpg',           // 抿嘴笑
