      皱眉嘟嘴: 'https://files.catbox.moe/1avdt9.jpg',            // 皱眉嘟嘴
      白眼: 'https://files.catbox.moe/anvb0b.jpg',         // 白眼
      闭眼龇牙笑: 'https://files.catbox.moe/xx0b4q.jpg',           // 闭眼龇牙笑
      张嘴皱眉: 'https://files.catbox.moe/p4gwbw.jpg',           // 张嘴皱眉
      闭单眼嘟嘴: 'https://files.catbox.moe/ov2b1m.jpg',            // 闭单眼嘟嘴
      皱眉小张嘴: 'https://files.catbox.moe/913bl2.jpg',        // 皱眉小张嘴
      闭眼流汗: 'https://files.catbox.moe/vvz9gy.jpg',           // 闭眼流汗
      睁眼哭: 'https://files.catbox.moe/cdvvlv.jpg',             // 睁眼哭
      闭眼笑: 'https://files.catbox.moe/cnbh79.jpg'      // 闭眼笑
    };

    // 根据心奈评分更新图片
    function updateImageByScore() {
      const evalTexts = document.querySelectorAll('.eval-text');
      const evalScores = document.querySelectorAll('.eval-score');

      // 检查彩蛋关键词（优先级高于评分）
      const totalComment = evalTexts[6].textContent.trim(); // 总评内容
      let imageUrl = '';

      // 彩蛋检查
      if (totalComment.includes('18cm')) {
        imageUrl = 'https://files.catbox.moe/xorjuj.png';
      } else if (totalComment.includes('恋童癖')) {
        imageUrl = 'https://files.catbox.moe/zuw6jy.png';
      } else if (totalComment.includes('受精')) {
        imageUrl = 'https://files.catbox.moe/k7d6wj.png';
      } else if (totalComment.includes('呜齁')) {
        imageUrl = 'https://files.catbox.moe/992qqj.png';
      } else if (totalComment.includes('中出')) {
        // 中出时随机选择两个图片中的一个
        const creampieImages = [
          'https://files.catbox.moe/mtbag0.png',
          'https://files.catbox.moe/5ibwsw.png'
        ];
        const randomIndex = Math.floor(Math.random() * creampieImages.length);
        imageUrl = creampieImages[randomIndex];
      } else {
        // 没有彩蛋关键词时，按评分选择图片
        let totalScore = 0;
        let validScores = 0;

        // 计算前6个评分的总和（不包括总评）
        for (let i = 0; i < 6; i++) {
          const scoreText = evalScores[i].textContent.trim();
          const score = parseFloat(scoreText);
          if (!isNaN(score)) {
            totalScore += score;
            validScores++;
          }
        }

        // 计算平均分
        const averageScore = validScores > 0 ? totalScore / 6 : 0;

        // 根据平均分选择图片
        if (averageScore < 40) {
          // 小于40分时随机选择3个图片中的一个
          const lowScoreImages = [
            'https://files.catbox.moe/o7943s.png',
            'https://files.catbox.moe/v3ubwf.png',
            'https://files.catbox.moe/5sbof3.png'
          ];
          const randomIndex = Math.floor(Math.random() * lowScoreImages.length);
          imageUrl = lowScoreImages[randomIndex];
        } else if (averageScore < 60) {
          imageUrl = 'https://files.catbox.moe/lu7f8j.png';
        } else if (averageScore < 80) {
          imageUrl = 'https://files.catbox.moe/biafs1.png';
        } else {
          imageUrl = 'https://files.catbox.moe/6f7389.png';
        }
      }

      // 更新图片
      const image = document.querySelector('.corner-image');
      if (image) {
        image.src = imageUrl;
      }
    }

