      // 移除现有的下划线容器
      const existingUnderlines = document.querySelector('.text-underline');
      if (existingUnderlines) {
        existingUnderlines.remove();
      }

      // 创建新的下划线容器
      const underlineContainer = document.createElement('div');
      underlineContainer.className = 'text-underline';
      contentEl.parentNode.insertBefore(underlineContainer, contentEl);

      // 获取所有文本节点和<br>标签
      const textNodes = [];
      const walker = document.createTreeWalker(
        contentEl,
        NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT,
        {
          acceptNode: function(node) {
            if (node.nodeType === Node.TEXT_NODE && node.textContent.trim()) {
              return NodeFilter.FILTER_ACCEPT;
            }
            if (node.nodeType === Node.ELEMENT_NODE && node.tagName === 'BR') {
              return NodeFilter.FILTER_ACCEPT;
            }
            if (node.nodeType === Node.ELEMENT_NODE && node.classList.contains('dialog-box')) {
              return NodeFilter.FILTER_SKIP;
            }
            return NodeFilter.FILTER_SKIP;
          }
        }
      );

      let currentNode;
      while (currentNode = walker.nextNode()) {
        if (currentNode.nodeType === Node.TEXT_NODE || currentNode.tagName === 'BR') {
          textNodes.push(currentNode);
        }
      }

      // 为每个文本段落添加下划线
      let currentY = 0;
      let lastWasBR = false;

      textNodes.forEach((node, index) => {
