      // 填充评测内容
      const evalTexts = document.querySelectorAll('.eval-text');
      const evalScores = document.querySelectorAll('.eval-score');

      for (let i = 0; i < 6 && i * 2 + 2 < parts.length; i++) {
        evalTexts[i].textContent = parts[i * 2 + 2] || '';
        evalScores[i].textContent = parts[i * 2 + 3] || '';
      }

      // 填充总评
