      const dialogRegex = /<([^|]+)\|([^|]+)\|([^>]+)>/g;

      return text.replace(dialogRegex, function(match, character, expression, dialogue) {
        // 获取表情对应的图片URL
        let avatarUrl = '';
        if (character === '心奈' && kokonaExpressions[expression]) {
          avatarUrl = kokonaExpressions[expression];
        } else {
          // 如果找不到对应表情，使用默认表情
          avatarUrl = kokonaExpressions.normal || 'https://files.catbox.moe/2wxy0m.jpg';
        }

        // 生成对话框HTML
        return `<div class="dialog-box">
          <img src="${avatarUrl}" alt="${character}" class="dialog-avatar">
          <div class="dialog-content">
            <div class="dialog-name">${character}</div>
            <div>${dialogue}</div>
          </div>
        </div>`;
      });
    }

    // 将当前正文的HTML转换为纯文本（对话框替换为“名字：内容”）并同步到测量容器
    function syncTextSizerFromContent() {
      const contentEl = document.querySelector('.letter-content');
      const textSizer = document.querySelector('.letter-text-sizer');
      const temp = document.createElement('div');
      temp.innerHTML = contentEl.innerHTML;
      const boxes = temp.querySelectorAll('.dialog-box');
      boxes.forEach((box) => {
        const name = box.querySelector('.dialog-name')?.textContent || '';
        const text = box.querySelector('.dialog-content div:last-child')?.textContent || '';
        const replacement = document.createElement('div');
        replacement.textContent = name ? `${name}：${text}` : text;
        box.replaceWith(replacement);
      });
      textSizer.textContent = temp.innerText || temp.textContent || '';
    }

    // 设置正文内容
    function setLetterContent() {

      // 查找<examination>标签的位置
      const examStart = fullInput.indexOf('<examination>');

      // 提取<examination>前面的内容作为正文
      let content = '';
      if (examStart !== -1) {
        content = fullInput.substring(0, examStart).trim();
      } else {
        content = fullInput;
      }

      // 先处理对话格式
      content = parseDialogFormat(content);

      // 将换行符转换为HTML换行标签
      content = content.replace(/\n/g, '<br>');

      const contentEl = document.querySelector('.letter-content');
      contentEl.innerHTML = content;
      // 生成下划线（只在非对话区域）
      setTimeout(generateUnderlines, 10);
    }

    // 随机旋转图片
    function randomRotateImage() {
      const image = document.querySelector('.corner-image');
      if (image) {
        // 生成-30到+30度之间的随机角度
        const randomAngle = (Math.random() - 0.5) * 60; // -30 到 +30 度
        image.style.transform = `rotate(${randomAngle}deg)`;
