        let totalScore = 0;
        let validScores = 0;

        // 计算前6个评分的总和（不包括总评）
        for (let i = 0; i < 6; i++) {
          const scoreText = evalScores[i].textContent.trim();
          const score = parseFloat(scoreText);
          if (!isNaN(score)) {
            totalScore += score;
            validScores++;
          }
        }

        // 计算平均分
        const averageScore = validScores > 0 ? totalScore / 6 : 0;

        // 根据平均分选择图片
        if (averageScore < 40) {
          // 小于40分时随机选择3个图片中的一个
