          imageUrl = lowScoreImages[randomIndex];
        } else if (averageScore < 60) {
          imageUrl = 'https://files.catbox.moe/lu7f8j.png';
        } else if (averageScore < 80) {
          imageUrl = 'https://files.catbox.moe/biafs1.png';
        } else {
          imageUrl = 'https://files.catbox.moe/6f7389.png';
        }
      }

      // 更新图片
      const image = document.querySelector('.corner-image');
      if (image) {
        image.src = imageUrl;
      }
    }

    // 横线相关监听已移除
    window.onload = function() {
